<style>.sk{display:grid;grid-template-columns:repeat(auto-fit,minmax(150px,1fr));gap:10px;margin-bottom:16px}.sk .card{margin:0;padding:12px}.sk span{font-size:12px;color:#6B7280;display:block}.sk b{font-size:22px;color:var(--n)}.bd{display:inline-block;font-size:11px;font-weight:700;border-radius:999px;padding:2px 9px;background:#F3F4F6;color:#374151}.bd.sent,.bd.completed,.bd.delivered{background:#DCFCE7;color:#166534}.bd.failed,.bd.rejected,.bd.cancelled,.bd.expired{background:#FEE2E2;color:#B91C1C}.bd.queued,.bd.sending,.bd.draft{background:#E0E7FF;color:#3730A3}.bd.scheduled{background:#E0F2FE;color:#075985}.bd.paused{background:#FEF3C7;color:#92400E}.sg label{display:inline-flex;gap:6px;align-items:center;border:1px solid var(--bd);border-radius:20px;padding:5px 11px;margin:0 6px 6px 0;font-size:12px;cursor:pointer;background:#fff}.sg input{width:auto;margin:0}.sg label:has(input:checked){background:#FFF1E8;border-color:#FF5A00;color:#C2410C;font-weight:700}.tw{overflow-x:auto}</style>
